SELECT COALESCE(SUM(online_minutes), 0)
FROM `wpcelib_player_online`
WHERE player_uuid = #{playerUuid,jdbcType=CHAR,javaType=java.util.UUID}
  AND stat_date BETWEEN #{startDate,jdbcType=DATE,javaType=java.time.LocalDate}
  AND #{endDate,jdbcType=DATE,javaType=java.time.LocalDate}
